DROP DATABASE IF EXISTS online_bookstore;
CREATE DATABASE online_bookstore CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE online_bookstore;
CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password_hash CHAR(64) NOT NULL,role ENUM('ADMIN','CUSTOMER') NOT NULL DEFAULT 'CUSTOMER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE authors(author_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,bio TEXT);
CREATE TABLE categories(category_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255));
CREATE TABLE books(book_id INT AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(30) NOT NULL UNIQUE,title VARCHAR(180) NOT NULL,author_id INT NOT NULL,category_id INT NOT NULL,price DECIMAL(10,2) NOT NULL,stock INT NOT NULL DEFAULT 0,format ENUM('PRINTED','EBOOK') NOT NULL DEFAULT 'PRINTED',description TEXT,image_url VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(author_id) REFERENCES authors(author_id),FOREIGN KEY(category_id) REFERENCES categories(category_id));
CREATE TABLE orders(order_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,book_id INT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('PENDING','PAID','SHIPPED','COMPLETED','CANCELLED') DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(book_id));
CREATE TABLE reviews(review_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,book_id INT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(600) NOT NULL,approved BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(book_id) REFERENCES books(book_id) ON DELETE CASCADE,CONSTRAINT chk_rating CHECK(rating BETWEEN 1 AND 5));
